// Dump a reset-baseline .bin (raw hybrid_state_v1) as name,addr,hex CSV.
#include "hybrid/state_abi.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>

int main(int argc, char** argv) {
  if (argc != 2) { fprintf(stderr, "usage: %s <baseline.bin>\n", argv[0]); return 2; }
  FILE* f = fopen(argv[1], "rb");
  if (!f) { perror("open"); return 1; }
  hybrid_state_v1 s;
  if (fread(&s, 1, sizeof s, f) != sizeof s) { fprintf(stderr, "short read\n"); return 1; }
  fclose(f);
  if (s.magic != HYBRID_STATE_MAGIC || s.version != HYBRID_STATE_VERSION) {
    fprintf(stderr, "bad magic/version\n"); return 1;
  }
  printf("field,csr_addr,value\n");
  printf("flags,-,0x%x\n", s.flags);
  printf("pc,-,0x%llx\n", (unsigned long long)s.pc);
  printf("priv,-,0x%llx\n", (unsigned long long)s.priv);
#define P(name, addr, v) printf("%s,%s,0x%llx\n", name, addr, (unsigned long long)(v))
  P("mstatus", "0x300", s.mstatus);
  P("mepc", "0x341", s.mepc);
  P("mtvec", "0x305", s.mtvec);
  P("mcause", "0x342", s.mcause);
  P("mtval", "0x343", s.mtval);
  P("mscratch", "0x340", s.mscratch);
  P("medeleg", "0x302", s.medeleg);
  P("mideleg", "0x303", s.mideleg);
  P("mip", "0x344", s.mip);
  P("mie", "0x304", s.mie);
  P("mcycle", "0xB00", s.mcycle);
  P("minstret", "0xB02", s.minstret);
  P("satp", "0x180", s.satp);
  for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
    char n[32], a[16]; snprintf(n, sizeof n, "pmpcfg%d", i);
    snprintf(a, sizeof a, "0x%X", 0x3A0 + i); P(n, a, s.pmpcfg[i]);
  }
  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
    char n[32], a[16]; snprintf(n, sizeof n, "pmpaddr%d", i);
    snprintf(a, sizeof a, "0x%X", 0x3B0 + i); P(n, a, s.pmpaddr[i]);
  }
  P("vstart", "0x008", s.vstart);
  P("vtype", "0xC21", s.vtype);
  P("vl", "0xC20", s.vl);
  P("vlenb", "0xC22", s.vlenb);
  P("vxsat", "0x009", s.vxsat);
  P("vxrm", "0x00A", s.vxrm);
  P("vcsr", "0x00F", s.vcsr);
  P("fcsr", "0x003", s.fcsr);
  P("mcache_ctl", "0x7CA", s.mcache_ctl);
  P("mmisc_ctl", "0x7D0", s.mmisc_ctl);
#define X(field, addr, name) { char a[16]; snprintf(a, sizeof a, "0x%03X", addr); P(name, a, s.andes.field); }
  HYBRID_ANDES_CSR_LIST(X)
#undef X
  for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
    char n[32], a[16]; snprintf(n, sizeof n, "pmacfg%d", i * 2);
    snprintf(a, sizeof a, "0x%X", 0xBC0 + i * 2); P(n, a, s.andes.pmacfg[i]);
  }
  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
    char n[32], a[16]; snprintf(n, sizeof n, "pmaaddr%d", i);
    snprintf(a, sizeof a, "0x%X", 0xBD0 + i); P(n, a, s.andes.pmaaddr[i]);
  }
#define X(field, addr, name) { char a[16]; snprintf(a, sizeof a, "0x%03X", addr); P(name, a, s.m_ext.field); }
  HYBRID_M_EXT_CSR_LIST(X)
#undef X
  return 0;
}

